  put(Q.judge("law-bal-judge-008", "law-main", "l10", "l10-s3", "学生提出合法异议，本身不能被自动视为新的违纪行为。", true, 1, "合理表达与法定救济应得到保障。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-009", "law-main", "l7", "l7-s2", "教育法律关系的内容通常表现为参加者的权利与义务。", true, 1, "主体、客体、内容是分析法律关系的基本要素。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-010", "law-main", "l2", "l2-s3", "教学楼作为物本身，与学校法人一样可以直接成为所有法律关系的权利主体。", true, 1, "物通常属于客体，不等同于享有权利义务的主体。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-011", "law-main", "l9", "l9-s1", "同一事件在符合不同法定条件时，可能涉及不止一种法律责任。", true, 1, "民事、行政或刑事责任是否并存应具体依法判断。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
