  put(Q.judge("law-bal-judge-013", "law-main", "l9", "l9-s2", "依法承担民事责任，不等于当然构成刑事犯罪。", true, 1, "不同责任类型适用不同法律条件。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-014", "law-main", "l1", "l1-s2", "只要发生了损害，就无需再分析适用规则和因果关系。", true, 1, "责任认定需要具体构成要件与证据。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-015", "law-main", "l1", "l1-s2", "教育活动中的合同关系和行政管理关系在法律性质上可能不同。", true, 1, "应根据主体地位和具体行为区分。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-016", "law-main", "l5", "l5-s2", "教师、学生和学校在法律关系中都只有义务而没有权利。", true, 1, "相关主体依法同时享有权利并承担义务。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-017", "law-main", "l2", "l2-s5", "教育法律与教育部门规章的制定主体和效力层级应当区分。", true, 1, "不能只根据文件标题判断规范层级。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-018", "law-main", "l2", "l2-s1", "教育部制定的所有文件都当然属于全国人大制定的国家法律。", true, 1, "法律、规章及其他文件的制定主体与性质不同。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-019", "law-main", "l2", "l2-s1", "判断规范是否适用，需要关注其生效、修改和废止情况。", true, 1, "应使用有效文本，避免把旧规定当作现行规则。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-020", "law-main", "l7", "l7-s1", "学校转发某文件后，就可以任意改变该文件规定的法定权利。", true, 1, "转发不产生改变上位规范的权限。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-021", "law-main", "l2", "l2-s5", "教育法律体系中的规范应按法定权限和程序制定。", true, 1, "制定权限和程序会影响规范的合法性。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-022", "law-main", "l2", "l2-s1", "只要文件更新日期较晚，其效力就必定高于所有较早法律。", true, 1, "新旧关系不能脱离效力层级和制定权限判断。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-023", "law-main", "l7", "l7-s2", "教育制度中的权利义务可以由任何个人口头承诺随意变更。", true, 1, "口头承诺不能突破法定权限及强制规定。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-024", "law-main", "l2", "l2-s1", "学校实施内部管理时，仍需依法接受相应监督。", true, 1, "管理自主不意味着不受监督。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-025", "law-main", "l2", "l2-s1", "公民依法平等享有受教育机会，并不意味着所有人必须取得同样成绩。", true, 1, "机会平等与结果完全一致不是同一概念。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
