  put(Q.judge("law-bal-judge-027", "law-main", "l2", "l2-s3", "国家教育考试制度可以直接与任何一次课堂提问画等号。", true, 1, "国家考试与日常教学评价有不同制度属性。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-028", "law-main", "l2", "l2-s3", "学业证书制度与学位制度有联系，但不能完全混为同一制度。", true, 1, "学历与学位的条件、功能和授予程序有区别。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-029", "law-main", "l2", "l2-s1", "继续教育仅指取得第一个学校学历之前的教育。", true, 1, "继续教育与终身学习包含不同人生阶段的学习。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-030", "law-main", "l7", "l7-s3", "学校可依法组织学生参与教育教学计划安排的活动。", true, 1, "活动应符合培养目标和相关管理要求。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
