  put(Q.judge("law-bal-judge-069", "law-main", "l4", "l4-s1", "教师资格考试题目、答案及评分标准的保密义务有法律依据。", true, 1, "泄露有关考试信息可能被依法追责。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-070", "law-main", "l4", "l4-s1", "高校教师资格认定可以由任何个人自行制作证书完成。", true, 1, "认定及发证须由有权机构依规定进行。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-071", "law-main", "l4", "l4-s2", "教师职务聘任应与岗位职责和相应任职条件相联系。", true, 1, "不能把聘任只当成与能力职责无关的称号。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-072", "law-main", "l4", "l4-s1", "只要校长口头同意，依法应履行的教师资格程序就全部免除。", true, 1, "个人意见不能任意替代法定条件和程序。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-073", "law-main", "l3", "l3-s4", "《学位法》将学位层次与学位类型分别作出规定。", true, 1, "学士、硕士、博士属于层次，学术、专业等属于类型。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-075", "law-main", "l3", "l3-s4", "学位授予单位需要具有相应学科或专业的授予资格。", true, 1, "有学校资格不等于具备所有学位授予资格。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-076", "law-main", "l3", "l3-s4", "专业学位只考察实践经历，不需要任何基础理论和专门知识。", true, 1, "专业学位也有相应层次的知识及能力要求。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-077", "law-main", "l3", "l3-s4", "硕士学位申请人应按规定完成课程、训练及相应答辩等环节。", true, 1, "学位要求不能简化为只看某一次出勤。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
