  put(Q.judge("law-bal-judge-079", "law-main", "l3", "l3-s4", "学位授予具体标准可以只保存在导师个人电脑中，始终不予公布。", true, 1, "学位授予单位应制定并公布具体标准。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-080", "law-main", "l10", "l10-s1", "拟不授予或撤销学位时，应告知有关事实理由依据并听取陈述申辩。", true, 1, "《学位法》第三十九条规定了相关保障。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-081", "law-main", "l10", "l10-s1", "对学术评价结论有异议，不能直接等同于对所有行政处理的同一种争议。", true, 1, "法律设置不同复核与处理渠道。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
