  put(Q.judge("law-bal-judge-104", "law-main", "l7", "l7-s1", "学生家庭经济困难时，学校就可以不经程序剥夺其人格尊严。", true, 1, "经济状况不能成为侵害人格权的理由。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-105", "law-main", "l7", "l7-s1", "学校管理人员不得以私人恩怨替代合法的学生评价标准。", true, 1, "管理行为应公正并有相应依据。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
