  put(Q.judge("law-bal-judge-107", "law-main", "l9", "l9-s2", "校园伤害归责应区分完全、限制及无民事行为能力等不同情形。", true, 1, "《民法典》对有关情形设置不同规则。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-108", "law-main", "l9", "l9-s2", "所有成年大学生的伤害案件，都应直接套用无民事行为能力人的过错推定规则。", true, 1, "行为能力和适用条款应具体核对。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-109", "law-main", "l9", "l9-s2", "学校未尽教育管理职责与损害之间的联系，是责任分析的重要因素。", true, 1, "不能脱离损害和因果关系单独归责。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-110", "law-main", "l9", "l9-s2", "任何事故只要发生在校内，学校必然承担全部赔偿责任。", true, 1, "地点不能代替职责、过错、因果关系等分析。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-111", "law-main", "l7", "l7-s2", "学生个人也有遵守安全要求、避免危及他人权益的义务。", true, 1, "学校安全职责不排除学生自身合理注意义务。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-112", "law-main", "l9", "l9-s2", "学校签订人身损害一概免责条款，就可以当然免除所有法定责任。", true, 1, "免责条款效力受法律限制。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-113", "law-main", "l9", "l9-s2", "对已知危险设施及时采取必要措施，是学校安全管理的重要内容。", true, 1, "不处理已知风险可能产生管理过错。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-114", "law-main", "l9", "l9-s2", "学生伤害由校外第三人造成时，所有情况下学校都自动承担唯一的直接责任。", true, 1, "应依法区分第三人责任和学校可能承担的相应责任。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-115", "law-main", "l9", "l9-s2", "针对无或限制民事行为能力学生的第三人侵害，学校未尽管理职责时可能承担补充责任。", true, 1, "《民法典》第一千二百零一条规定了相应规则。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-116", "law-main", "l9", "l9-s2", "无民事行为能力学生在校受伤时，学校不能以已经尽到教育管理职责提出任何抗辩。", true, 1, "第一千一百九十九条允许学校证明尽责而不承担相应责任。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-117", "law-main", "l9", "l9-s2", "限制民事行为能力学生在校受伤，学校未尽教育管理职责的，应依法承担相应责任。", true, 1, "第一千二百条需结合具体损害事实适用。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-118", "law-main", "l9", "l9-s2", "学校安全责任与监护人监护责任不能在所有场景下简单画等号。", true, 1, "法定教育管理职责与监护职责应区分。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.judge("law-bal-judge-119", "law-main", "l9", "l9-s2", "事故后合理保全相关记录，有助于查明事实和依法处理争议。", true, 1, "应合法保存证据，不得伪造或故意毁损。"), "现行法规知识点平衡补充·自编（v1.10.0）；1.14.0目录复核");
  put(Q.single("law-r12-single-001", "law-main", "l1", "l1-s1", "教育法制建设的直接目的之一是（　　）。", ["把教育活动和教育管理纳入法治轨道", "用政策口号替代法律规范", "将学校变成行政机关", "取消教育活动中的权利义务"], "A", 2, "教育法制通过规范教育关系、权利义务和治理程序保障教育秩序。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.single("law-r12-single-003", "law-main", "l5", "l5-s1", "教师权利与义务的关系，正确的理解是（　　）。", ["履行义务意味着没有任何权利", "教师权利可以由个人口头放弃全部", "权利与义务相互联系并受法律边界约束", "享有权利即可不履行职责"], "C", 2, "教师法同时规定教师权利与义务，学校管理须在法定边界内平衡两者。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.single("law-r12-single-004", "law-main", "l1", "l1-s2", "依法治教要求教育管理活动首先依据（　　）开展。", ["未经公布的口头要求", "现行有效且适用于该事项的法律规范", "校内临时通知即可", "管理者个人经验"], "B", 2, "依法治教要求行政机关和学校在法定权限、程序及有效规范范围内办事。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.single("law-r12-single-005", "law-main", "l1", "l1-s3", "高校制定学生管理规定时，最基本的合法性要求是（　　）。", ["不得与法律、法规和规章相抵触，并依规定程序制定公布", "校长签字后即可排除法律约束", "可以限制法律明确保障的申诉权", "可对已经发生的行为任意溯及加重"], "A", 2, "学校规章应在上位法框架内制定实施，不能用内部规则排除法定权利。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.single("law-r12-single-006", "law-main", "l2", "l2-s2", "校规与国家法律发生冲突时，适用规则的判断首先应考虑（　　）。", ["哪份文件发布时间较晚", "校规是否更方便管理", "由学生自行选择", "规范的制定权限、效力层级和适用范围"], "D", 2, "文件日期不当然决定效力高低，须依法判断权限、层级及适用范围。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.single("law-r12-single-007", "law-main", "l2", "l2-s5", "教育部门规章要对外发生规范效力，依法应当（　　）。", ["由学校自行转发后即视为法律", "可以不说明施行时间和适用范围", "由有权机关依程序制定并公布", "只需在内部会议上口头通过"], "C", 2, "部门规章须由有权机关依立法权限和程序制定、公布。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.single("law-r12-single-008", "law-main", "l3", "l3-s2", "《高等教育法》规定，高等学校开展教学、科研和社会服务，应当以（　　）为中心。", ["争取科研项目数量", "培养人才", "扩大招生规模", "增加经营收益"], "B", 2, "《高等教育法》第三十一条明确高校以培养人才为中心，并开展教学、科研和社会服务。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.single("law-r12-single-010", "law-main", "l2", "l2-s3", "教育法律规范的内容主要表现为教育法律关系主体的（　　）。", ["兴趣和习惯", "职位和收入", "荣誉和声望", "权利和义务"], "D", 2, "教育法律关系的内容通常表现为主体依法享有的权利和承担的义务。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.single("law-r12-single-011", "law-main", "l3", "l3-s4", "高校取得办学自主权后，授予学位仍须（　　）。", ["只要在校章程中写入即可", "无须遵守国家学位标准", "依法取得相应学位授予资格并遵守学位法", "由校长个人决定"], "C", 2, "办学自主权不等于可自行取得学位授予资格；学位授予须遵守《学位法》。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.single("law-r12-single-012", "law-main", "l4", "l4-s1", "取得高校教师资格与获得某所高校的具体教师岗位之间的关系是（　　）。", ["两者属于同一法律程序", "资格是职业准入条件之一，具体岗位还须依聘任程序确定", "取得资格即自动获得编制岗位", "获得博士学位即当然取得教师资格"], "B", 2, "教师资格与岗位聘任分别属于资格认定和用人关系，不可混同。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.single("law-r12-single-013", "law-main", "l4", "l4-s2", "高校教师职务系列包括（　　）。", ["助教、讲师、副教授、教授", "教员、讲师、高级讲师、教授", "讲师、副教授、教授、研究员", "助教、讲师、主任、副校长"], "A", 2, "《高等教育法》规定高校教师职务设助教、讲师、副教授、教授。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.single("law-r12-single-014", "law-main", "l4", "l4-s3", "高校与教师订立聘任合同，应遵循（　　）原则。", ["学校单方任意决定", "教师必须接受任何变更", "以校内通知代替双方意思表示", "双方平等自愿"], "D", 2, "《高等教育法》规定高校教师聘任应遵循双方平等自愿原则，由校长与受聘教师签订聘任合同。"), "按用户提供法规目录补充的自编题（1.14.0）");
