  put(Q.single("law-r12-single-016", "law-main", "l5", "l5-s3", "教师履行教育教学职责时，依法应当（　　）。", ["可以用体罚替代教育管理", "关心、爱护全体学生并尊重学生人格", "可以因学生申诉而加重处分", "可以公开学生隐私以便管理"], "B", 2, "《教师法》规定教师应关心爱护全体学生、尊重学生人格，不得实施侵害行为。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.single("law-r12-single-017", "law-main", "l6", "l6-s2", "高校依据《教师法》考核教师时，考核内容包括（　　）。", ["政治思想、业务水平、工作态度和工作成绩", "仅看科研经费", "仅由学生投票决定", "只看出勤，不考虑岗位职责"], "A", 2, "《教师法》规定学校或者其他教育机构应对教师进行考核，内容包括上述四项。"), "按用户提供法规目录补充的自编题（1.14.0）");
