  put(Q.judge("law-r12-judge-004", "law-main", "l2", "l2-s5", "已经废止或失效的规范，不应作为当前处分决定的有效依据。", true, 1, "作出决定时应核对规范的现行效力状态。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-005", "law-main", "l3", "l3-s2", "高校以培养人才为中心开展教学、科学研究和社会服务。", true, 1, "这是《高等教育法》第三十一条的规定。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-006", "law-main", "l3", "l3-s3", "高校依法享有办学自主权，因此可以不受教育质量标准约束。", true, 1, "办学自主权须在法律框架内行使，高校仍须保障教育教学质量。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-007", "law-main", "l3", "l3-s1", "高校取得法人资格后，其校长个人即成为学校财产所有人。", true, 1, "高校法人与校长是不同法律主体，学校财产不因此成为校长个人财产。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-008", "law-main", "l4", "l4-s1", "具备教师资格认定所需学历，仍不等于自动满足全部资格条件。", true, 1, "教师资格认定还涉及思想品德、教育教学能力及依法规定的其他条件。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-009", "law-main", "l4", "l4-s2", "助教、讲师、副教授、教授构成高校教师职务序列。", true, 1, "《高等教育法》规定高校教师职务设助教、讲师、副教授、教授。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-010", "law-main", "l4", "l4-s3", "高校教师聘任原则上遵循双方平等自愿，并由高校校长与受聘教师签订聘任合同。", true, 1, "《高等教育法》对高校教师聘任作了明确规定。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-011", "law-main", "l5", "l5-s1", "教师法定权利与岗位职责可以同时存在，不能以履行职责为由取消其全部权利。", true, 1, "权利义务并存，学校管理须尊重教师依法享有的权利。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-012", "law-main", "l5", "l5-s2", "教师享有指导学生学习发展和评定学生品行、学业成绩的权利，但应依法、公正履职。", true, 1, "指导和评价权不意味着可以任意评价或损害学生权益。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-013", "law-main", "l5", "l5-s3", "学生有异议时，教师可以用体罚作为教育教学管理手段。", true, 1, "教师应依法履行教育教学和保护学生义务，体罚不是法定权利。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-014", "law-main", "l6", "l6-s1", "教师与学校的关系应结合聘任合同、法律法规及具体管理行为判断。", true, 1, "高校教师聘任关系不能一概等同于行政机关内部人事关系。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-015", "law-main", "l6", "l6-s2", "学校对教师开展考核时，应按岗位要求和适用制度进行，不得以私人恩怨替代客观依据。", true, 1, "教师法要求对教师进行考核，相关决定应依法依规并公正实施。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-016", "law-main", "l6", "l6-s3", "教师通过教职工代表大会参与民主管理，不等于直接取代校长行使学校法定职权。", true, 1, "参与民主管理与学校法定治理分工可以并存。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-017", "law-main", "l10", "l10-s3", "学生依法享有申诉权，并不意味着所有申诉当然获得支持。", true, 1, "申诉是程序性救济权，处理结果仍须依事实和规范作出。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-018", "law-main", "l7", "l7-s2", "学生依法享有权利，因此无须遵守合法的学校管理制度。", true, 1, "权利与义务并存；学生须遵守法律法规和合法校规。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-019", "law-main", "l7", "l7-s3", "教师依法开展教育教学和学校管理，不当然使教师成为学生的监护人。", true, 1, "学校教育管理职责与监护职责应依法区分。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-020", "law-main", "l7", "l7-s4", "退学处理与警告、严重警告、记过、留校察看、开除学籍等纪律处分属于不同管理类别。", true, 1, "学生管理规定区分学籍处理与纪律处分，具体行为应按相应程序处理。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-021", "law-main", "l8", "l8-s1", "社会支持和监督高等教育，应通过法律允许的方式进行。", true, 1, "社会参与不能替代高校和行政机关依法承担的职责。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-022", "law-main", "l8", "l8-s2", "教师作为履行教育教学职责的专业人员，其职业活动具有法定权利义务边界。", true, 1, "教师专业身份并不赋予其超越法律的权力。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-023", "law-main", "l8", "l8-s3", "教师在校外开展专业服务，也可能因其身份、合同或具体行为承担相应法律责任。", true, 1, "责任应依行为、身份、授权与法律关系判断，不能只看地点。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-024", "law-main", "l9", "l9-s1", "同一事实在符合不同法律构成要件时，可能同时产生不同性质的责任。", true, 1, "民事、行政或刑事责任须分别满足各自法定条件。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-025", "law-main", "l9", "l9-s2", "学生伤害发生在校园内，学校就必然承担全部赔偿责任。", true, 1, "学校责任须按行为能力、法定义务、过错或其他适用归责规则分析。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-026", "law-main", "l9", "l9-s3", "某行为受到校内纪律处理，不能据此直接推定行为人已构成犯罪。", true, 1, "刑事责任须依法满足犯罪构成并经法定程序认定。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-027", "law-main", "l9", "l9-s4", "教师违反法定义务时，学校或教育行政部门只能给予道德批评，不能依法处理。", true, 1, "教师法对特定违法失职行为规定了行政处分、解聘等处理方式。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-028", "law-main", "l10", "l10-s1", "选择教育争议救济渠道时，应先判断争议属于何种法律关系及法律有无特别程序。", true, 1, "教师申诉、学生申诉、行政复议及诉讼等程序的适用范围并不相同。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-029", "law-main", "l10", "l10-s2", "教师对学校或其他教育机构侵犯其合法权益的，可以依规定向教育行政部门提出申诉。", true, 1, "《教师法》第三十九条规定教师申诉渠道及行政部门处理期限。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.judge("law-r12-judge-030", "law-main", "l10", "l10-s3", "学生校内申诉期限与教师向教育行政部门提出申诉的期限，应按各自适用规范区分。", true, 1, "教师法与学生管理规定分别规定不同主体的申诉程序和期限。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.blank("law-r12-blank-001", "law-main", "l3", "l3-s2", "《高等教育法》规定，高等学校应当以培养____为中心。", ["人才"], 2, "《高等教育法》第三十一条明确高校以培养人才为中心。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.blank("law-r12-blank-002", "law-main", "l6", "l6-s1", "《高等教育法》规定，高等学校的校长为学校的法定____。", ["代表人"], 2, "《高等教育法》第三十条规定高校校长为学校法定代表人。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.blank("law-r12-blank-003", "law-main", "l8", "l8-s2", "《教师法》规定，教师是履行教育教学职责的____人员。", ["专业"], 2, "《教师法》第三条规定教师是履行教育教学职责的专业人员。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.blank("law-r12-blank-004", "law-main", "l10", "l10-s2", "教师对学校或其他教育机构的处理不服提出申诉，教育行政部门应当自收到申诉之日起____日内作出处理。", ["30", "三十"], 2, "《教师法》第三十九条规定教育行政部门应在接到申诉的三十日内作出处理。"), "按用户提供法规目录补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-001", "law-main", "l1", "l1-s3", "依法治校的基本边界是（　　）。", ["法律、法规和规章", "管理便利", "个人口头要求", "网络投票结果"], "A", 2, "校内规则和管理行为不得超越上位法和法定权限。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-001", "law-main", "l1", "l1-s3", "依法治校要求学校管理行为同时接受权限、程序和救济规则约束。", true, 1, "依法治校不仅是制定校规，还包括依法行使管理权并提供救济。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-001", "law-main", "l1", "l1-s3", "学校处理学生重大权益事项时，通常应当做到（　　）。", ["说明事实、理由和依据", "告知陈述申辩或申诉渠道", "以未公布口径直接处理", "禁止学生查阅与本人有关的决定"], ["A", "B"], 3, "重大权益事项应遵循正当程序并保障学生程序性权利。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.blank("law-r13-blank-001", "law-main", "l1", "l1-s3", "学校规章不得与有效的____法相抵触。", ["上位"], 2, "校规属于下位规范，不能排除上位法要求。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-002", "law-main", "l2", "l2-s2", "教育法的公法属性主要体现在其调整（　　）。", ["国家教育管理与教育活动中的公共权利义务关系", "私人赠与关系", "企业股东关系", "家庭继承关系"], "A", 2, "教育法的重要面向是公共治理和受教育权保障。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-002", "law-main", "l2", "l2-s2", "教育法的性质应结合调整对象和规范内容判断，不能只看法律名称。", true, 1, "法律性质需要结合其调整对象、权利义务和治理关系判断。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-002", "law-main", "l2", "l2-s2", "判断教育法在法律体系中的地位，应当关注（　　）。", ["调整对象", "规范效力和制定权限", "文件篇幅", "学校转载次数"], ["A", "B"], 3, "法律地位不能由篇幅或转载情况决定。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-003", "law-main", "l2", "l2-s2", "教育法保护受教育者权利，也规定教育行政机关、学校和教师的法定义务。", true, 1, "教育法同时具有权利保障和公共管理规范功能。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.blank("law-r13-blank-002", "law-main", "l2", "l2-s2", "教育法调整教育活动及其管理中的法律____。", ["关系"], 2, "教育法律关系由主体、客体和内容等要素构成。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-004", "law-main", "l2", "l2-s2", "教育法属于教育领域的专门法律规范，但其实施仍须符合宪法和上位法。", true, 1, "专门性不意味着可以脱离上位法体系。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-003", "law-main", "l2", "l2-s4", "判断教育规范是否具有相应效力，首先应核实其（　　）。", ["制定主体和法定权限", "标题是否醒目", "是否被多数学校转发", "文字是否较长"], "A", 2, "制定权限是判断规范效力的重要前提。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-005", "law-main", "l2", "l2-s4", "部门规章与法律、行政法规在制定主体和效力层级上并不相同。", true, 1, "规范层级取决于制定主体、权限和法律规定。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-006", "law-main", "l2", "l2-s4", "同一事项存在不同规范时，不能只按发布时间先后判断适用效力。", true, 1, "还需比较权限、层级、特别规定和现行有效状态。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.blank("law-r13-blank-003", "law-main", "l2", "l2-s4", "法律、行政法规、部门规章之间存在规范____关系。", ["层级"], 2, "不同规范的效力与制定权限存在层级差异。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-007", "law-main", "l2", "l2-s4", "已经废止的规范原则上不能作为当前学校处分决定的现行依据。", true, 1, "作出决定时应核对规范的有效状态和适用时间。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-004", "law-main", "l2", "l2-s4", "核对教育规范的现行状态时，应检查（　　）。", ["是否仍有效", "是否已被修改、废止或替代", "是否被搜索引擎置顶", "是否与个人观点一致"], ["A", "B"], 3, "时效性核对是法规题答案复核的必要步骤。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-008", "law-main", "l5", "l5-s3", "教师履行教育教学职责时，应遵守宪法、法律和职业道德。", true, 1, "教师法对教师履职义务作出明确要求。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-005", "law-main", "l5", "l5-s3", "为落实《教师法》规定的履职义务，教师应当（　　）。", ["完成教育教学任务", "关心爱护学生并尊重学生人格", "公开学生隐私", "以体罚替代教育"], ["A", "B"], 3, "教师义务包括完成任务和保护学生合法权益。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-004", "law-main", "l6", "l6-s1", "判断高校教师与学校关系时，应综合考虑（　　）。", ["聘任合同、法律规定和具体管理行为", "只看职称", "只看内部通知", "只看工资发放"], "A", 2, "高校教师法律关系不能用单一标签概括。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-009", "law-main", "l6", "l6-s1", "高校教师与学校之间可能同时存在聘任合同关系和教育法律关系。", true, 1, "合同、岗位管理和教师法定权利义务可以同时构成关系内容。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-006", "law-main", "l6", "l6-s1", "高校教师聘任关系的判断可以参考（　　）。", ["双方意思表示和合同内容", "岗位职责及适用法律制度", "校长个人喜好", "未经公布的传闻"], ["A", "B"], 3, "关系认定应基于可核实的法律事实。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
