  put(Q.blank("law-r13-blank-004", "law-main", "l6", "l6-s1", "高校与教师订立聘任合同，应遵循平等____原则。", ["自愿"], 2, "高等教育法规定高校教师聘任应遵循双方平等自愿。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-005", "law-main", "l6", "l6-s2", "学校对教师进行考核时，主要应依据（　　）。", ["岗位职责和法定、制度化考核标准", "私人关系", "网络传闻", "临时偏好"], "A", 2, "教师考核应有客观依据并遵循公正程序。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-011", "law-main", "l6", "l6-s2", "教师考核结果可以依法作为聘任、晋升、奖惩等管理事项的参考。", true, 1, "教师法规定学校对教师进行考核，考核结果可作为相关管理依据。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-007", "law-main", "l6", "l6-s2", "高校教师管理决定应当注意（　　）。", ["事实依据充分", "程序和救济渠道明确", "只凭匿名传闻定案", "禁止教师说明情况"], ["A", "B"], 3, "管理决定需要事实、程序和救济保障。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-012", "law-main", "l6", "l6-s2", "学校对教师作出不利处理时，可以完全不告知理由。", true, 1, "不利处理应在适用制度范围内说明事实依据并保障程序权利。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.blank("law-r13-blank-005", "law-main", "l6", "l6-s2", "教师考核内容包括政治思想、业务水平、工作态度和工作____。", ["成绩"], 2, "教师法列明教师考核的基本内容。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-013", "law-main", "l6", "l6-s2", "学校管理教师时，应把依法管理与保障教师合法权利结合起来。", true, 1, "依法管理是在法定边界内行使管理权。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-006", "law-main", "l8", "l8-s2", "教师社会地位的法律基础之一是教师属于履行教育教学职责的（　　）。", ["专业人员", "普通行政工作人员", "学校财产管理人", "国家所有权代表"], "A", 2, "教师法确立教师专业人员定位并要求尊重教师。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-014", "law-main", "l8", "l8-s2", "尊重教师社会地位，不等于赋予教师超越法律的特权。", true, 1, "教师专业地位与法定权利义务边界并存。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-008", "law-main", "l8", "l8-s2", "教师社会作用通常体现为（　　）。", ["人才培养", "知识传播和社会服务", "任意行使处罚权", "替代国家机关制定法律"], ["A", "B"], 3, "教师作用与教育教学、科研和社会服务职责相联系。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-015", "law-main", "l8", "l8-s2", "教师的社会声誉可以替代学校对教师职业行为的制度管理。", true, 1, "社会尊重不能代替依法管理、考核和监督。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.blank("law-r13-blank-006", "law-main", "l8", "l8-s2", "教师是履行教育教学职责的____人员。", ["专业"], 2, "该表述来自教师法关于教师职业定位的规定。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-007", "law-main", "l8", "l8-s3", "教师参与社会服务活动时，首先应当遵守（　　）。", ["法律法规、合同约定和职业规范", "合作方所有要求", "未经授权的利益安排", "网络投票结果"], "A", 2, "社会服务仍受法律关系和职业边界约束。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-016", "law-main", "l8", "l8-s3", "教师在校外实施的行为，可能因合同、授权或侵权事实产生法律责任。", true, 1, "责任判断取决于行为和法律关系，不只看发生地点。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-009", "law-main", "l8", "l8-s3", "高校与社会组织合作时，应明确（　　）。", ["双方权利义务", "成果使用和责任承担", "允许合作方任意改变结论", "以合同排除法定义务"], ["A", "B"], 3, "合作协议应明确权责和成果安排。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-017", "law-main", "l8", "l8-s3", "教师接受社会合作项目经费后，可以不履行合同约定的报告和成果义务。", true, 1, "经费、合同和成果义务应按约履行并接受监督。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.blank("law-r13-blank-007", "law-main", "l8", "l8-s3", "教师社会服务中的权利义务通常由法律、合同和实际____共同确定。", ["行为"], 2, "责任不能只依据身份或地点判断。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-018", "law-main", "l8", "l8-s3", "社会组织支持高等教育，不当然取得学校学位授予或教师考核权。", true, 1, "社会合作不得替代高校法定治理职能。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-008", "law-main", "l9", "l9-s3", "判断教育活动是否涉及刑事责任，关键要看是否符合（　　）。", ["刑法规定的犯罪构成和法定程序", "舆论批评", "校园地点", "校内警告"], "A", 2, "校内处理和舆论评价不能代替刑事认定。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-019", "law-main", "l9", "l9-s3", "受到学校纪律处分，不等于已经被认定构成犯罪。", true, 1, "刑事责任须经法定程序并满足犯罪构成。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-010", "law-main", "l9", "l9-s3", "教育活动中的刑事责任判断应关注（　　）。", ["行为要件", "主观责任和法定程序", "媒体热度", "职务名称"], ["A", "B"], 3, "刑事责任必须依刑法构成和程序判断。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-020", "law-main", "l9", "l9-s3", "只要造成学生不满，教师就当然承担刑事责任。", true, 1, "不满或争议本身不等于犯罪。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
