  put(Q.single("law-r13-single-009", "law-main", "l9", "l9-s4", "教师违反教育法律法规但尚不构成犯罪的，可能依法承担（　　）。", ["行政处分或其他法定处理", "自动晋升", "只接受劝告", "当然免除责任"], "A", 2, "责任处理须依具体违法事实和适用规范确定。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-022", "law-main", "l9", "l9-s4", "行政责任与刑事责任的成立条件和处理程序不同。", true, 1, "行政处理不能直接代替刑事认定。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-023", "law-main", "l9", "l9-s4", "学校可以依据未公布的内部口头要求直接给予教师法定处分。", true, 1, "处分应有公开有效的规范依据和正当程序。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.blank("law-r13-blank-009", "law-main", "l9", "l9-s4", "行政处分应当由有权机关依照法定权限和____作出。", ["程序"], 2, "权限和程序是行政责任处理的基本要求。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-024", "law-main", "l9", "l9-s4", "教师受到行政处分后，仍可依法行使陈述、申辩或申诉等程序性权利。", true, 1, "责任处理与程序救济并不矛盾。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-010", "law-main", "l10", "l10-s1", "选择教育争议救济方式时，首先应判断（　　）。", ["争议主体、行为性质和适用程序", "舆论热度", "是否能绕过程序", "个人偏好"], "A", 2, "不同法律关系对应不同救济渠道。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-025", "law-main", "l10", "l10-s1", "申诉、行政复议、行政诉讼和民事诉讼的适用条件并不完全相同。", true, 1, "救济方式须依争议性质和法律规定选择。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-014", "law-main", "l10", "l10-s1", "教育争议救济的基本功能包括（　　）。", ["纠正可能的违法或不当处理", "保障相关主体依法表达和获得审查", "以舆论替代裁判", "自动保证申诉成立"], ["A", "B"], 3, "救济提供程序保障，但不预先决定实体结果。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
