  put(Q.blank("law-r13-blank-010", "law-main", "l10", "l10-s1", "教育法律救济应当遵循有权机关、适用程序和法定____。", ["期限"], 2, "不同救济途径通常有不同主体、程序和期限。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-011", "law-main", "l10", "l10-s1", "当事人认为教育管理行为侵害其合法权益时，救济方式应依（　　）确定。", ["行为性质和适用法律规定", "舆论声量", "个人身份高低", "学校是否同意接受监督"], "A", 2, "救济途径须根据法律关系、行为性质及特别程序选择。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-027", "law-main", "l10", "l10-s1", "不同法律救济程序可能适用不同的申请主体、受理机关和期限。", true, 1, "具体救济条件由相应法律规范规定。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-012", "law-main", "l10", "l10-s3", "学生对学校处分复查决定仍有异议的，应依规定向（　　）提出后续申诉。", ["省级教育行政部门", "任意社会组织", "高校学术委员会", "公安机关"], "A", 2, "普通高校学生管理规定设有向省级教育行政部门申诉的后续程序。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-028", "law-main", "l10", "l10-s3", "学生在校内申诉期间，学校不得因学生提出申诉而加重对其的处理。", true, 1, "学生管理规定要求保障申诉权，不得因申诉加重处理。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-013", "law-main", "l3", "l3-s2", "高等教育法的任务和方针应当在（　　）框架内理解。", ["国家教育方针和法律规定", "单个学校偏好", "社会舆论热度", "临时项目要求"], "A", 2, "高校办学任务须以国家教育方针和现行法律为依据。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-029", "law-main", "l6", "l6-s1", "高校与教师订立聘任合同后，合同约定可以排除适用的强制性法律规范。", true, 1, "高校教师聘任应依法订立并履行合同，合同约定不能排除强制性规定。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.blank("law-r13-blank-011", "law-main", "l6", "l6-s1", "高校聘任教师，应遵循双方平等____的原则。", ["自愿"], 2, "《高等教育法》规定，高校教师聘任应遵循双方平等自愿的原则。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-015", "law-main", "l3", "l3-s3", "高校依法行使办学自主权时，应当同时遵守（　　）。", ["国家法律法规", "教育质量和办学规范", "与法律冲突的赞助方要求", "未经授权的个人指令"], ["A", "B"], 3, "自主办学与依法办学、质量保障相统一。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-030", "law-main", "l3", "l3-s3", "高校享有办学自主权，因此可以不受国家教育质量标准约束。", true, 1, "办学自主权不能排除法定质量标准和监督要求。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-031", "law-main", "l9", "l9-s1", "法律责任的认定应当以违法事实、损害后果和适用责任规则为基础。", true, 1, "责任不能仅凭身份、地点或舆论评价推定。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-015", "law-main", "l6", "l6-s1", "高校教师与学校发生聘任争议时，首先应核对（　　）。", ["聘任合同及其适用的法律规范", "未经核实的口头传闻", "与岗位无关的私人评价", "其他学校的内部惯例"], "A", 2, "聘任关系应结合合同文本、相关法律和具体履行事实判断。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-032", "law-main", "l6", "l6-s1", "高校教师岗位聘任的法律关系，应仅凭教师是否具有教师资格作出判断。", true, 1, "教师资格是准入条件，岗位聘任还涉及合同和岗位安排。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-016", "law-main", "l6", "l6-s2", "学校开展教师考核时，适当的做法包括（　　）。", ["考核内容与岗位职责相联系", "考核过程有记录并允许教师了解结果", "仅凭匿名传言决定结果", "使用未告知的临时标准"], ["A", "B"], 3, "考核应有岗位依据并兼顾程序公正。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-033", "law-main", "l6", "l6-s2", "教师考核应当与教师所承担的岗位职责和工作实际相关。", true, 1, "岗位职责和实际工作是考核的重要依据。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-016", "law-main", "l6", "l6-s3", "教师参与学校民主管理的主要方式之一是（　　）。", ["通过教职工代表大会或其他适当形式提出意见建议", "个人直接替代校长行使职权", "不经程序决定全部校务", "代替学位评定委员会授予学位"], "A", 2, "教师依法可以通过教代会或其他形式参与学校民主管理。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-017", "law-main", "l8", "l8-s1", "社会依法参与和支持高等教育，可以包括（　　）。", ["依法开展校企合作和社会服务", "依法对教育活动进行社会监督", "擅自决定高校招生录取", "代替高校作出教师处分决定"], ["A", "B"], 3, "社会参与应在法律权限内进行，不能取代高校法定职责。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-034", "law-main", "l8", "l8-s1", "社会组织提供教育合作资源后，即当然取得对高校教学和学位授予的决定权。", true, 1, "合作资源不产生法定办学或学位授予权限。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-017", "law-main", "l8", "l8-s2", "教师的专业社会地位与其法律责任之间的关系是（　　）。", ["专业地位受到尊重，同时仍须依法履行职责并承担相应责任", "专业地位使其免于法律约束", "教师当然具有公务员身份", "教师可以代表学校行使一切职权"], "A", 2, "专业身份与法律责任并存，尊重教师不等于赋予免责特权。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-035", "law-main", "l8", "l8-s2", "教师职业具有专业性，因此教师的权利义务均由法律和相关制度规范。", true, 1, "教师专业性与法定职业边界相统一。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-018", "law-main", "l8", "l8-s3", "教师与社会主体开展合作时，依法应当关注（　　）。", ["是否具有适当授权", "合作内容、利益冲突和责任边界", "合作方是否承诺免除全部责任", "是否可以绕开学校制度"], ["A", "B"], 3, "授权、合作范围和利益冲突是社会合作合规审查的重要内容。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-036", "law-main", "l8", "l8-s3", "教师以个人身份签订的社会服务合同，不会产生任何法律义务。", true, 1, "合同义务应依签约主体、授权和合同内容判断。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-018", "law-main", "l9", "l9-s1", "教育法律责任的基本含义是违反法定义务后依法承担的（　　）。", ["不利法律后果", "社会荣誉", "工作奖励", "自动免责"], "A", 2, "法律责任以违反法定义务并满足相应归责条件为基础。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-037", "law-main", "l9", "l9-s1", "法律责任的性质和种类，应根据具体行为和适用规范判断。", true, 1, "责任不能仅依据行为人身份或事件发生地点推定。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-019", "law-main", "l9", "l9-s3", "对可能构成犯罪的行为作出定罪判断，依法应由（　　）依照法定程序进行。", ["有权司法机关", "学校内部会议", "媒体平台", "学生申诉委员会"], "A", 2, "学校可依规管理和移送线索，但不能代替司法机关定罪。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-038", "law-main", "l9", "l9-s3", "校内调查结论可以直接代替人民法院作出刑事定罪。", true, 1, "校内调查不能替代刑事司法程序和有权机关的认定。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-019", "law-main", "l9", "l9-s4", "处理教师违法失职行为时，应当区分（　　）。", ["教育行政处分与学校内部管理措施", "违法事实与一般工作评价", "批评与刑事定罪完全相同", "任何处分都导致教师资格自动撤销"], ["A", "B"], 3, "处理类型及法律后果应依据具体法律规范，不能相互替代。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-039", "law-main", "l9", "l9-s4", "教师资格处理、岗位处理和行政处分属于不同制度，不能不加区分地视为同一法律后果。", true, 1, "教师资格、岗位聘任和处分分别适用不同的条件与程序。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-020", "law-main", "l10", "l10-s1", "判断受教育者可以采取何种法律救济时，首先应当依据（　　）。", ["所受处理的性质、被侵害的权益及适用法律规定", "一律先提行政诉讼", "一律只能向学校内部申诉", "由学校单方指定且不受法律约束"], "A", 2, "教育法分别规定对学校处分提出申诉，以及合法权益受侵害时提出申诉或依法提起诉讼；具体途径需结合争议性质判断。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-020", "law-main", "l10", "l10-s1", "依据《教育法》关于受教育者权利的规定，下列救济表述正确的有（　　）。", ["对学校给予的处分不服，可以向有关部门提出申诉", "学校、教师侵犯其人身权、财产权等合法权益时，可以提出申诉或者依法提起诉讼", "任何校内管理争议都必须先申请行政复议", "提出申诉后原决定当然失效"], ["A", "B"], 3, "《教育法》确认对处分申诉的权利，也规定对人身权、财产权等合法权益受侵害时可申诉或依法起诉；它没有把所有争议限定为同一救济程序。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-040", "law-main", "l10", "l10-s3", "普通高校学生申诉处理委员会可以由学校相关负责人、职能部门负责人、教师代表、学生代表及负责法律事务的相关机构负责人等组成，并可以聘请校外法律、教育等方面专家参加。", true, 1, "《普通高等学校学生管理规定》第六十条规定了申诉处理委员会的组成，并允许聘请校外法律、教育等方面专家参加。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-041", "law-main", "l10", "l10-s3", "学生申诉处理委员会可以在收到书面申诉之日起30个工作日内作出复查结论；该期限与省级教育行政部门处理后续申诉的期限相同。", true, 1, "学校学生申诉处理委员会应在收到书面申诉之日起15日内作出复查结论并告知学生；30个工作日是省级教育行政部门处理后续书面申诉的期限。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-021", "law-main", "l1", "l1-s1", "教育领域制定和实施管理规范时，确定规范适用依据应首先遵循（　　）。", ["依法制定且仍然有效的规范及其权限层级", "未公开的内部意见", "搜索结果排序", "单个学校的惯例"], "A", 2, "规范适用要核对制定主体、法定权限、效力层级及现行有效状态。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-022", "law-main", "l1", "l1-s2", "教育行政机关对学校实施监督时，依法行政的基本要求是（　　）。", ["在法定职权范围内并依照法定程序实施", "可以不说明权限来源", "可由口头惯例取代规范依据", "监督目的正当即可不受程序约束"], "A", 2, "教育行政监督须有法定职权依据，并遵循适用程序。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-023", "law-main", "l1", "l1-s3", "学校制定内部管理规则时，应当优先确保规则（　　）。", ["不与法律法规相抵触，并符合法定权限和程序", "可以限制上位法规定的权利", "只需经校内口头同意", "无须向受规则影响者公开"], "A", 2, "内部规则不得突破上位法和法定权限，制定、公布也应符合适用要求。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-024", "law-main", "l6", "l6-s1", "判断高校与教师之间某项权利义务是否属于聘任合同内容，应重点审查（　　）。", ["合同约定、相关法律规范及实际履行情况", "教师职称这一单一因素", "其他高校未公开的惯例", "与聘任无关的个人评价"], "A", 2, "聘任关系应结合合同条款、法律制度和实际履行事实认定。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-042", "law-main", "l6", "l6-s1", "高校依法与教师订立聘任合同后，合同约定仍须符合强制性法律规范。", true, 1, "合同约定不能排除适用的强制性规范。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-025", "law-main", "l6", "l6-s2", "高校评价教师是否完成岗位职责，应以（　　）为基本依据。", ["已明确的岗位职责、考核标准和可核实的工作事实", "未经核实的匿名传言", "与岗位无关的私人关系", "临时设置且未告知的标准"], "A", 2, "岗位管理和考核应依据明确标准与可核实事实，并遵循适用程序。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-021", "law-main", "l6", "l6-s2", "高校对教师开展岗位考核时，规范做法包括（　　）。", ["考核标准与岗位职责相联系", "按既定程序记录并处理考核结果", "以个人好恶代替工作事实", "以未告知的新标准追溯评价"], ["A", "B"], 3, "考核应以岗位职责和明确标准为依据，并按程序实施。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-026", "law-main", "l6", "l6-s3", "教师参与高校民主管理时，适当做法是（　　）。", ["通过教职工代表大会等适当形式依法表达意见和建议", "不经授权直接替代学校负责人决策", "取代法定学术组织行使专属职权", "以个人意见废止学校依法作出的决定"], "A", 2, "教师可以通过教代会等形式参与民主管理，但应遵守学校治理权限和程序。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-r13-single-027", "law-main", "l8", "l8-s1", "社会主体为高校提供经费或合作资源后，其权利范围通常应由（　　）确定。", ["法律规定及双方合法有效的协议", "资源金额单方面决定", "合作方内部口头安排", "与项目无关的社会舆论"], "A", 2, "资源支持不当然转移高校法定职权，合作权利义务应依法依约确定。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-022", "law-main", "l8", "l8-s2", "理解高校教师的社会地位与作用，应当认识到（　　）。", ["教师承担教育教学、人才培养等专业职责", "教师专业地位与法定权利义务并存", "专业身份当然使教师免于法律责任", "教师身份自动取得行政机关职权"], ["A", "B"], 3, "教师的专业性和社会作用应与其依法履职、承担责任相结合。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-043", "law-main", "l8", "l8-s2", "尊重教师的专业地位，意味着学校不得对教师依法履职情况进行任何考核。", true, 1, "尊重教师与依法开展岗位管理、考核并不矛盾。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.multiple("law-r13-multiple-023", "law-main", "l8", "l8-s3", "高校教师开展校外合作或社会服务时，应重点核实（　　）。", ["是否取得必要授权并符合学校制度", "合同、成果使用及责任边界是否明确", "合作方承诺可以免除法律责任", "是否能绕过利益冲突审查"], ["A", "B"], 3, "合作应符合授权和制度要求，并通过协议明确成果与责任。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.judge("law-r13-judge-044", "law-main", "l8", "l8-s3", "教师参与社会服务项目时，即使以个人名义签约，也应结合签约主体、授权和合同内容判断相应义务。", true, 1, "合同责任取决于具体签约关系、授权情况和约定内容。"), "按法规目录薄弱章节补充的自编题（1.14.0）");
  put(Q.single("law-sup-001", "law-main", "l1", "l1-s1", "教育法制的基本要求是（　　）", ["有法可依、有法必依、执法必严、违法必究", "以德治国", "行政命令", "政策引导"], "A", 2, "教育法制的基本要求即有法可依、有法必依、执法必严、违法必究。"), "原题库");
  put(Q.single("law-sup-002", "law-main", "l1", "l1-s1", "我国教育法制建设的核心是（　　）", ["依法治教", "以德治教", "行政化管理", "市场化"], "A", 2, "依法治教是教育法制建设的核心。"), "原题库");
  put(Q.judge("law-sup-003", "law-main", "l1", "l1-s1", "教育法制只指教育立法。", true, 1, "教育法制包括教育立法、执法、司法与监督等环节。"), "原题库");
  put(Q.judge("law-sup-004", "law-main", "l1", "l1-s1", "教育行政执法是教育法制的重要环节。", true, 1, "教育行政执法是教育法制实施的重要环节。"), "原题库");
  put(Q.multiple("law-sup-005", "law-main", "l1", "l1-s1", "教育法制包括（　　）", ["教育立法", "教育执法", "教育司法", "教育监督"], ["A", "B", "C", "D"], 3, "教育法制覆盖立法、执法、司法与监督。"), "原题库");
  put(Q.blank("law-sup-006", "law-main", "l1", "l1-s1", "教育法制的基本要求可概括为“有法可依、有法必依、____、违法必究”。", ["执法必严"], 2, "完整表述为有法可依、有法必依、执法必严、违法必究。"), "原题库");
  put(Q.single("law-sup-007", "law-main", "l1", "l1-s1", "我国教育领域的基本法律是（　　）", ["《教育法》", "《教师法》", "《高等教育法》", "《学位条例》"], "A", 2, "《教育法》是我国教育领域的基本法律。"), "原题库");
  put(Q.judge("law-sup-008", "law-main", "l1", "l1-s1", "《教育法》是我国教育领域的基本法律。", true, 1, "《教育法》在教育法律体系中居于基本法地位。"), "原题库");
  put(Q.single("law-sup-009", "law-main", "l1", "l1-s2", "依法治教的主体是（　　）", ["国家机关、学校及其他教育机构、社会组织和公民", "仅教育行政机关", "仅学校", "仅教师"], "A", 2, "依法治教主体具有广泛性。"), "原题库");
  put(Q.judge("law-sup-010", "law-main", "l1", "l1-s2", "依法治教要求教育行政机关依法行政。", true, 1, "教育行政机关必须依法行政。"), "原题库");
  put(Q.judge("law-sup-011", "law-main", "l1", "l1-s2", "依法治教就是学校自主办学、不受监督。", true, 1, "依法治教同时要求依法监督。"), "原题库");
  put(Q.multiple("law-sup-012", "law-main", "l1", "l1-s2", "依法治教的内容包括（　　）", ["依法行政", "依法治校", "依法执教", "依法监督"], ["A", "B", "C", "D"], 3, "依法行政、依法治校、依法执教与依法监督共同构成依法治教。"), "原题库");
  put(Q.blank("law-sup-013", "law-main", "l1", "l1-s2", "依法治教要求教育行政部门做到____行政。", ["依法"], 2, "教育行政部门应当依法行政。"), "原题库");
  put(Q.single("law-sup-014", "law-main", "l1", "l1-s2", "教育行政执法的依据是（　　）", ["教育法律法规", "领导指示", "学校规章", "习惯做法"], "A", 2, "教育行政执法必须以教育法律法规为依据。"), "原题库");
  put(Q.judge("law-sup-015", "law-main", "l1", "l1-s2", "教育行政处罚属于教育行政执法行为。", true, 1, "行政处罚是行政执法的一种方式。"), "原题库");
  put(Q.short("law-sup-016", "law-main", "l1", "l1-s2", "简述依法治教的基本要求。", "一是做到有法可依，健全教育法律体系；二是依法行政，教育行政机关依法履职；三是依法治校，学校依章程和制度办学；四是依法执教，教师依法履行权利义务；五是健全监督与救济机制。", ["有法可依", "依法行政", "依法治校", "依法执教", "监督", "权利义务"], 10, "从立法、行政、学校、教师、监督五方面作答。"), "原题库");
  put(Q.single("law-sup-017", "law-main", "l1", "l1-s3", "依法治校的核心是（　　）", ["依章程办学、按制度管理", "校长个人说了算", "以罚代管", "封闭管理"], "A", 2, "依法治校强调依章程和制度治理学校。"), "原题库");
  put(Q.single("law-sup-018", "law-main", "l1", "l1-s3", "学校章程在依法治校中的地位是（　　）", ["学校的基本制度依据", "可有可无", "仅用于备案", "只在评奖时使用"], "A", 2, "章程是学校依法办学的基本依据。"), "原题库");
  put(Q.judge("law-sup-019", "law-main", "l1", "l1-s3", "依法治校要求学校建立健全内部管理制度。", true, 1, "完善内部管理制度是依法治校的基础。"), "原题库");
  put(Q.judge("law-sup-020", "law-main", "l1", "l1-s3", "依法治校意味着学校可以自行设定行政处罚。", true, 1, "学校无权设定行政处罚，处罚须有法律依据。"), "原题库");
  put(Q.multiple("law-sup-021", "law-main", "l1", "l1-s3", "依法治校的内容包括（　　）", ["依法制定章程", "完善内部治理", "保障师生权益", "接受监督"], ["A", "B", "C", "D"], 3, "依法治校涵盖章程、治理、权益保障与监督。"), "原题库");
  put(Q.blank("law-sup-022", "law-main", "l1", "l1-s3", "依法治校要求学校依照____自主办学。", ["章程"], 2, "学校依章程自主办学。"), "原题库");
  put(Q.single("law-sup-023", "law-main", "l1", "l1-s3", "学校对学生的处分应当（　　）", ["事实清楚、依据明确、程序正当", "由班主任决定", "不必告知", "可以随意"], "A", 2, "处分应当事实清楚、依据明确、程序正当。"), "原题库");
  put(Q.judge("law-sup-024", "law-main", "l1", "l1-s3", "校规与法律法规冲突时，应以法律法规为准。", true, 1, "校规不得与法律法规相抵触。"), "原题库");
  put(Q.single("law-sup-025", "law-main", "l5", "l5-s1", "教师权利与义务的关系是（　　）", ["相互依存、不可分割", "只讲权利", "只讲义务", "相互对立"], "A", 2, "教师权利与义务相互依存、具有一致性。"), "原题库");
  put(Q.judge("law-sup-026", "law-main", "l5", "l5-s1", "教师依法享有权利，也必须履行义务。", true, 1, "权利与义务相统一。"), "原题库");
  put(Q.judge("law-sup-027", "law-main", "l5", "l5-s1", "教师的权利可以随意放弃而不承担后果。", true, 1, "教师权利行使受法律约束，不得损害他人权益。"), "原题库");
  put(Q.multiple("law-sup-028", "law-main", "l5", "l5-s1", "教师权利义务的特点包括（　　）", ["法定性", "职业性", "权利义务一致性", "随意性"], ["A", "B", "C"], 3, "教师权利义务具有法定性、职业性与一致性。"), "原题库");
  put(Q.blank("law-sup-029", "law-main", "l5", "l5-s1", "《教师法》规定教师权利义务，体现了权利与义务的____性。", ["一致", "统一"], 2, "权利与义务具有一致性。"), "原题库");
  put(Q.single("law-sup-030", "law-main", "l5", "l5-s1", "教师权利的法律来源主要是（　　）", ["《教师法》等法律法规", "学校口头承诺", "家长要求", "学生意见"], "A", 2, "教师权利由法律法规规定。"), "原题库");
  put(Q.judge("law-sup-031", "law-main", "l5", "l5-s1", "教师行使权利不得损害国家、社会、学校和他人的合法权益。", true, 1, "权利行使须在法律范围内。"), "原题库");
  put(Q.short("law-sup-032", "law-main", "l5", "l5-s1", "简述教师权利与义务的关系。", "教师权利与义务相互依存、不可分割：权利是履行义务的条件，义务是享有权利的保障；二者具有一致性，都由法律法规规定，教师行使权利不得损害国家、社会、学校和他人的合法权益。", ["相互依存", "一致性", "合法"], 10, "从相互依存、一致性、法律约束三方面作答。"), "原题库");
  put(Q.single("law-sup-033", "law-main", "l5", "l5-s2", "教师有权进行教育教学活动，这属于（　　）", ["教育教学权", "科研权", "管理学生权", "报酬权"], "A", 2, "教育教学权是教师最基本的权利。"), "原题库");
  put(Q.single("law-sup-034", "law-main", "l5", "l5-s2", "教师有权指导学生学习、评定学生品行和学业成绩，这属于（　　）", ["管理学生权", "教育教学权", "民主管理权", "进修权"], "A", 2, "指导与评定学生属于管理学生权。"), "原题库");
  put(Q.judge("law-sup-035", "law-main", "l5", "l5-s2", "教师有权参加进修或者其他方式的培训。", true, 1, "进修培训权是教师法定权利。"), "原题库");
  put(Q.judge("law-sup-036", "law-main", "l5", "l5-s2", "教师有权对学校教育教学工作提出意见和建议。", true, 1, "民主管理权包括提出意见建议。"), "原题库");
  put(Q.blank("law-sup-037", "law-main", "l5", "l5-s2", "教师有权按时获取工资报酬，享受国家规定的福利待遇以及____带薪休假。", ["寒暑假"], 2, "教师享有寒暑假带薪休假。"), "原题库");
  put(Q.single("law-sup-038", "law-main", "l5", "l5-s2", "教师对学生进行体罚侵犯了学生的（　　）", ["人身权", "受教育权", "财产权", "知识产权"], "A", 2, "体罚侵犯学生人身权。"), "原题库");
  put(Q.judge("law-sup-039", "law-main", "l5", "l5-s2", "教师的教育教学权不受任何限制。", true, 1, "教师行使权利须遵守法律法规和职业道德。"), "原题库");
  put(Q.short("law-sup-040", "law-main", "l5", "l5-s2", "简述教师依法享有的主要权利。", "一是教育教学权；二是科学研究权；三是管理学生权；四是获取报酬待遇权；五是民主管理权；六是进修培训权。", ["教育教学权", "科学研究权", "管理学生权", "获取报酬", "民主管理", "进修培训"], 10, "按六项法定权利作答。"), "原题库");
  put(Q.single("law-sup-041", "law-main", "l5", "l5-s3", "教师贯彻国家教育方针、执行学校教学计划、完成教育教学任务，属于（　　）", ["教育教学义务", "关爱学生义务", "提高水平义务", "制止有害行为义务"], "A", 2, "完成教育教学工作是教师的基本义务。"), "原题库");
  put(Q.single("law-sup-042", "law-main", "l5", "l5-s3", "教师关心爱护全体学生、尊重学生人格，属于（　　）", ["关爱学生义务", "遵纪守法义务", "提高水平义务", "民主管理义务"], "A", 2, "关爱学生、尊重人格是教师义务。"), "原题库");
  put(Q.multiple("law-sup-043", "law-main", "l5", "l5-s3", "教师应当履行的义务包括（　　）", ["遵纪守法", "贯彻教育方针", "关爱学生", "制止有害行为"], ["A", "B", "C", "D"], 3, "教师法规定六项义务。"), "原题库");
  put(Q.judge("law-sup-044", "law-main", "l5", "l5-s3", "教师应当制止有害于学生的行为或者其他侵犯学生合法权益的行为。", true, 1, "制止有害行为是教师法定义务。"), "原题库");
  put(Q.judge("law-sup-045", "law-main", "l5", "l5-s3", "教师应当不断提高思想政治觉悟和教育教学业务水平。", true, 1, "提高水平是教师义务之一。"), "原题库");
  put(Q.blank("law-sup-046", "law-main", "l5", "l5-s3", "教师应当制止有害于学生的行为，批评和抵制有害于学生____的现象。", ["健康成长"], 2, "教师应抵制有害于学生健康成长的现象。"), "原题库");
  put(Q.single("law-sup-047", "law-main", "l5", "l5-s3", "教师不得体罚或变相体罚学生，体现了（　　）", ["关爱学生、尊重人格的义务", "科研义务", "管理义务", "进修义务"], "A", 2, "禁止体罚体现尊重学生人格的义务。"), "原题库");
  put(Q.judge("law-sup-048", "law-main", "l5", "l5-s3", "教师可以利用职务之便向学生推销商品谋取利益。", true, 1, "教师不得利用职务之便谋取私利。"), "原题库");
  put(Q.single("law-sup-049", "law-main", "l8", "l8-s1", "社会力量依法举办高等教育机构，属于（　　）", ["社会在高等教育方面的权利", "政府专有权力", "学校内部事务", "教师个人行为"], "A", 2, "社会力量依法办学是社会参与高等教育的权利。"), "原题库");
  put(Q.judge("law-sup-050", "law-main", "l8", "l8-s1", "国家鼓励企业事业组织、社会团体及其他社会组织和个人依法举办高等教育机构。", true, 1, "法律鼓励社会力量依法办学。"), "原题库");
  put(Q.judge("law-sup-051", "law-main", "l8", "l8-s1", "社会组织不得干涉学校正常的教育教学活动。", true, 1, "社会参与须尊重学校办学自主权。"), "原题库");
  put(Q.multiple("law-sup-052", "law-main", "l8", "l8-s1", "社会在高等教育方面的权利包括（　　）", ["依法办学", "捐资助学", "参与合作", "监督评价"], ["A", "B", "C", "D"], 3, "社会可依法办学、捐资、合作与监督。"), "原题库");
  put(Q.blank("law-sup-053", "law-main", "l8", "l8-s1", "国家鼓励社会力量依法举办高等教育机构，并保障其____权益。", ["合法"], 2, "社会力量办学的合法权益受法律保护。"), "原题库");
  put(Q.single("law-sup-054", "law-main", "l8", "l8-s1", "社会捐资助学属于（　　）", ["社会参与高等教育的权利", "行政处罚", "学校收费", "教师义务"], "A", 2, "捐资助学是社会参与教育的权利。"), "原题库");
  put(Q.judge("law-sup-055", "law-main", "l8", "l8-s1", "社会力量办学必须遵守国家法律法规。", true, 1, "社会力量办学须依法进行。"), "原题库");
  put(Q.short("law-sup-056", "law-main", "l8", "l8-s1", "简述社会在高等教育方面的权利与义务。", "权利方面：依法举办高等教育机构、捐资助学、参与合作、监督评价。义务方面：遵守国家法律法规，尊重学校办学自主权，不得干涉学校正常教育教学活动，保障受教育者合法权益。", ["监督", "捐资助学", "参与合作", "监督评价", "合法"], 10, "从办学、捐资、合作、监督与守法作答。"), "原题库");
  put(Q.single("law-sup-057", "law-main", "l8", "l8-s2", "教师的社会地位主要取决于（　　）", ["教师职业的专业性和社会贡献", "教师个人财富", "学校规模", "学生人数"], "A", 2, "教师社会地位取决于职业专业性与社会贡献。"), "原题库");
  put(Q.single("law-sup-058", "law-main", "l8", "l8-s2", "我国将教师定位为（　　）", ["履行教育教学职责的专业人员", "国家公务员", "自由职业者", "企业员工"], "A", 2, "《教师法》将教师定位为专业人员。"), "原题库");
  put(Q.multiple("law-sup-059", "law-main", "l8", "l8-s2", "教师社会地位的体现包括（　　）", ["政治地位", "经济地位", "职业声望", "法律地位"], ["A", "B", "C", "D"], 3, "教师社会地位体现在政治、经济、职业声望与法律地位。"), "原题库");
  put(Q.judge("law-sup-060", "law-main", "l8", "l8-s2", "全社会应当尊重教师。", true, 1, "尊师重教是法定要求。"), "原题库");
  put(Q.judge("law-sup-061", "law-main", "l8", "l8-s2", "教师的平均工资水平应当不低于当地公务员的平均工资水平。", true, 1, "《教师法》规定教师工资不低于或高于公务员平均工资水平。"), "原题库");
  put(Q.blank("law-sup-062", "law-main", "l8", "l8-s2", "《教师法》规定，教师的平均工资水平应当不低于或者高于国家____的平均工资水平。", ["公务员"], 2, "教师工资参照公务员平均工资水平。"), "原题库");
  put(Q.single("law-sup-063", "law-main", "l8", "l8-s2", "教师节是每年的（　　）", ["9月10日", "10月1日", "5月1日", "6月1日"], "A", 2, "我国教师节为9月10日。"), "原题库");
  put(Q.judge("law-sup-064", "law-main", "l8", "l8-s2", "教师的社会地位与教师队伍素质无关。", true, 1, "教师队伍素质影响教师社会地位。"), "原题库");
  put(Q.short("law-sup-065", "law-main", "l8", "l8-s2", "简述提高教师社会地位的主要途径。", "一是法律保障，落实教师法定权利与待遇；二是提高经济待遇，保障工资与福利；三是弘扬尊师重教的社会风尚；四是推进教师专业化，提高队伍素质；五是完善教师参与学校管理的机制。", ["专业", "尊师重教"], 10, "从法律、待遇、风尚、专业化、管理参与作答。"), "原题库");
  put(Q.single("law-sup-066", "law-main", "l8", "l8-s3", "教师在社会活动中应当（　　）", ["遵守法律、维护学校声誉", "只对学生负责", "不受约束", "以营利为目的"], "A", 2, "教师在社会活动中应守法并维护学校声誉。"), "原题库");
  put(Q.judge("law-sup-067", "law-main", "l8", "l8-s3", "教师可以以学校名义从事与教育教学无关的营利活动。", true, 1, "教师不得以学校名义从事无关营利活动。"), "原题库");
  put(Q.judge("law-sup-068", "law-main", "l8", "l8-s3", "教师参加社会服务应当遵守法律法规和学术规范。", true, 1, "社会服务须守法并遵守学术规范。"), "原题库");
  put(Q.multiple("law-sup-069", "law-main", "l8", "l8-s3", "教师与社会的关系包括（　　）", ["社会服务", "学术交流", "公共文化传播", "依法纳税"], ["A", "B", "C", "D"], 3, "教师与社会存在服务、交流、文化传播与纳税等关系。"), "原题库");
  put(Q.blank("law-sup-070", "law-main", "l8", "l8-s3", "教师参与社会服务应当正确处理教学、科研与____的关系。", ["社会服务"], 2, "教学、科研与社会服务应协调。"), "原题库");
  put(Q.single("law-sup-071", "law-main", "l8", "l8-s3", "教师在校外兼职应当（　　）", ["遵守学校规定，不影响本职工作", "随意兼职", "无需报备", "可占用工作时间"], "A", 2, "校外兼职须遵守学校规定且不影响本职工作。"), "原题库");
  put(Q.judge("law-sup-072", "law-main", "l8", "l8-s3", "教师应当自觉维护社会公共利益。", true, 1, "教师应维护社会公共利益。"), "原题库");
  put(Q.short("law-sup-073", "law-main", "l8", "l8-s3", "简述教师与社会法律关系的基本要求。", "教师应当遵守法律法规和学术规范，依法参与社会服务、学术交流与公共文化传播；正确处理教学、科研与社会服务的关系，校外兼职须遵守学校规定、不影响本职工作；不得以学校名义从事无关营利活动，自觉维护学校声誉和社会公共利益。", ["社会服务", "学术规范"], 10, "从守法、服务、兼职规范、维护公共利益作答。"), "原题库");
  put(Q.single("law-sup-074", "law-main", "l6", "l6-s1", "高校教师与学校之间的法律关系，本质上是一种（　　）", ["以聘任合同为基础的法律关系", "纯粹的行政隶属关系", "民事买卖关系", "无法律关系"], "A", 2, "教师与学校关系以聘任合同为基础。"), "原题库");
  put(Q.judge("law-sup-075", "law-main", "l6", "l6-s1", "教师与学校的法律关系只受《教师法》调整。", true, 1, "还受《高等教育法》《劳动合同法》等调整。"), "原题库");
  put(Q.multiple("law-sup-076", "law-main", "l6", "l6-s1", "高校教师与学校法律关系的类型包括（　　）", ["聘任关系", "管理关系", "权利义务关系", "监督关系"], ["A", "B", "C", "D"], 3, "教师与学校存在聘任、管理、权利义务与监督关系。"), "原题库");
